{
  "findings": [
    {
      "ref": "[D502]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child.",
      "stance": "risk",
      "quote": "When you join a virtual event hosted by a Creator, data such as your username, email, and Roblox user ID may be shared with the company that hosts the events. This is done to allow you to log in to the experience. Your activity during a Creator Event is subject to the third party platform’s privacy policy as well as the Roblox Community Standards. Creator events are only available if you are 13 or older."
    },
    {
      "ref": "[D502]",
      "area": "money",
      "claim": "A parent reports that the app pushes in-app purchases and loot boxes.",
      "stance": "risk",
      "quote": "When you subscribe to other features or activities that are available to users 13 years old or older, we’ll set out what information is collected and how we intend to use it when the information is collected."
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that the app tracks user behavior for ads and shares data with third parties.",
      "stance": "risk",
      "quote": "We process your Personal Information to display ads on Roblox. Specifically, we use information we collect to decide which ads to show you on Roblox."
    },
    {
      "ref": "[D502]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, requiring users to be 13 or older for certain features.",
      "stance": "mitigation",
      "quote": "Creator events are only available if you are 13 or older."
    },
    {
      "ref": "[D502]",
      "area": "content",
      "claim": "A parent reports that the app shows personalized ads to users 18 and older, while under‑18 users see only non‑personalized ads.",
      "stance": "neutral",
      "quote": "Users under 18 years old will see only nonpersonalized ads. Users 18 years old and older will see personalized ads on Roblox (with consent, where required)."
    },
    {
      "ref": "[D502]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny and fines for data collection.",
      "stance": "risk",
      "quote": "We update this Privacy Policy at times, so you should review this page regularly. We always publish the date of the latest version at the bottom of this page."
    }
  ]
}
